$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'next_setup_cpu.ps1')
$sy=[Collections.Generic.Dictionary[string,int]]::new();Get-Content (Join-Path $PSScriptRoot 'wifi_setup_next.sym')|ForEach-Object{if($_ -match '^v0\.([^:]+): EQU 0x([0-9A-Fa-f]+)'){$sy[$matches[1]]=[Convert]::ToInt32($matches[2],16)}}
$bin=[IO.File]::ReadAllBytes((Join-Path $PSScriptRoot 'wifi_setup_next18.bin'))
function Assert($v,$why){if(-not $v){throw $why}}
function Cpu{$c=[NextSetupCpu]::new([byte[]]@(),$sy,$sy['bios_start']);[Array]::Copy($bin,0,$c.M,0xC000,$bin.Length);$c.SP=0x6B00;$c.IX=$sy['flag1'];return $c}
$count=0
foreach($speed in 0..3){$c=Cpu;$c.IX=0x7ABC;$c.IY=0x5C3A;$c.AltH=0x27;$c.AltL=0x58;$c.CpuSpeed=$speed;$c.StopAt=$sy['st1'];$c.Run('start_ldir');Assert ($c.CpuSpeed -eq 0 -and $c.M[$sy['return_speed']+1] -eq $speed -and $c.Prescaler -eq 243 -and $c.Uart -eq 0 -and $c.Frame -eq 24) 'Startup CPU/UART';Assert ($c.SP -eq 0x63DE -and $c.M[$sy['next_baud']] -eq 7) 'Startup stack/cache';for($i=0;$i -lt 5314;$i++){Assert ($c.M[30000+$i] -eq $c.M[$sy['terminal_code']+$i]) 'Terminal copy'};$c.StopAt=-1;$c.IY=0x1111;$c.AltH=0xAB;$c.AltL=0xCD;$c.Run('quit');Assert ($c.CpuSpeed -eq $speed -and $c.SP -eq 0x6B00 -and $c.IX -eq 0x7ABC -and $c.IY -eq 0x5C3A -and $c.AltH*256+$c.AltL -eq 0x2758) 'Exit CPU/stack';foreach($port in $c.OutPorts){Assert ($port -in @(0x133B,0x143B,0x153B,0x163B,0x243B,0x253B) -or ($port-band 255) -eq 254) 'Legacy startup/exit port'};$count++}
$freq=@(28000000,28571429,29464286,30000000,31000000,32000000,33000000,27000000)
$rates=@(2400,4800,9600,19200,31250,38400,57600,115200,230400,460800,576000,921600,1152000,1500000,2000000)
foreach($timing in 0..7){foreach($speed in 0..14){$c=Cpu;$c.Timing=$timing;$c.Run('bios_start');$c.IX=$sy['flag1'];$c.A=$speed;$c.Run('set_print_speed');Assert (-not $c.Carry() -and $c.M[$sy['next_baud']] -eq $speed -and $c.Prescaler -eq [int][Math]::Floor($freq[$timing]/$rates[$speed]+0.5)) 'Set/cache UART';$writes=$c.OutPorts.Count;$c.Run('get_baud');Assert (-not $c.Carry() -and $c.A -eq $speed -and $c.EndBC()*[Math]::Pow(10,$c.E) -eq $rates[$speed]) 'Cached baud nominal info';$ports=@($c.OutPorts.GetRange($writes,$c.OutPorts.Count-$writes));Assert ($ports -notcontains 0x143B -and $ports -notcontains 0x153B) 'Baud query changed UART';$count++}}
$c=Cpu;$c.M[$sy['next_baud']]=255;$c.Run('get_baud');Assert ($c.Carry() -and $c.A -eq 255 -and $c.EndBC() -eq 0 -and $c.E -eq 0) 'Unknown baud result';$count++
foreach($text in @('-12','-2','-1','-0','0','1','+1','2','+2','12','14','+14')){$c=Cpu;$c.Put($sy['INPBUFF'],$text);$c.M[$sy['INLEN']]=$text.Length;$c.Run('next_timezone_parse');Assert (-not $c.Carry() -and $c.A -eq (([int]$text)-band 255)) ('Timezone '+$text);$count++}
foreach($text in @('','+','-','15','-13','99','abc','1x','1.5',' 1','1 ','++1','--1')){$c=Cpu;$c.Put($sy['INPBUFF'],$text);$c.M[$sy['INLEN']]=$text.Length;$c.Run('next_timezone_parse');Assert ($c.Carry()) ('Invalid timezone '+$text);$count++}
$rtc=[byte[]]@(0x56,0x34,0x12,6,0x06,0x11,0x26)
$c=Cpu;[Array]::Copy($rtc,0,$c.M,$sy['rtc_entry'],7);$c.Run('next_rtc_write');Assert (-not $c.Carry() -and $c.I2cTransactions.Count -eq 2) 'RTC write result';Assert (($c.I2cTransactions[0]-join ',') -eq ((@(208,0)+$rtc)-join ',')) 'RTC date bytes';Assert (($c.I2cTransactions[1]-join ',') -eq '208,62,90,88') 'RTC ZX signature';Assert ($c.Scl -eq 1 -and $c.Sda -eq 1 -and -not $c.I2cActive) 'RTC STOP';$count++
foreach($nack in 0..12){$c=Cpu;$c.NackAt=$nack;[Array]::Copy($rtc,0,$c.M,$sy['rtc_entry'],7);$c.Run('next_rtc_write');Assert ($c.Carry() -and $c.Scl -eq 1 -and $c.Sda -eq 1 -and -not $c.I2cActive) 'RTC NACK/STOP';$count++}
foreach($fault in @('NoRtc','SclStuck','SdaStuck')){$c=Cpu;$c.$fault=$true;$c.Run('next_rtc_write');Assert ($c.Carry()) ('RTC fault '+$fault);$count++}
foreach($zone in @(-12,-2,-1,0,1,2,14)){$c=Cpu;$c.Run('bios_start');$c.IX=$sy['flag1'];$c.RtcScenario=$true;$c.M[$sy['next_timezone']]=[byte]($zone-band 255);$c.StopAt=$sy['klAP_ret'];$c.Run('set_rtc');Assert ($c.Commands[0] -eq ('AT+CIPSNTPCFG=1,'+$zone+',"tik.cesnet.cz","time.nist.gov","cz.pool.ntp.org"'+"`r`n")) 'Actual SNTP timezone command';Assert (($c.I2cTransactions[0]-join ',') -eq ((@(208,0)+$rtc)-join ',')) 'SNTP parsed clock differs from RTC payload';$count++}
foreach($module in 0..14){$c=Cpu;$c.Run('bios_start');$c.IX=$sy['flag1'];$c.M[$sy['next_baud']]=255;$c.M[$sy['flag1']+8]=14;$c.SpeedScenario=$true;$c.ModuleIndex=$module;$c.Run('find_out_speed');Assert ($c.Zero() -and $c.D -eq $module -and $c.M[$sy['next_baud']] -eq $module) 'Unknown UART did not rescan/align';Assert ($c.ATChecks.Count -eq 15-$module) 'Unexpected scan count';$count++}
$c=Cpu;$c.Run('bios_start');$c.IX=$sy['flag1'];$c.M[$sy['flag1']+8]=14;$c.SpeedScenario=$true;$c.ModuleIndex=-1;$c.Run('switch_speed');Assert (-not $c.Zero() -and $c.ATChecks.Count -eq 15) 'No-answer scan not bounded to all 15 speeds';$count++
$c=Cpu;$c.StopAt=$sy['kl1'];$c.Run('start_ldir');Assert ($c.PC -eq $sy['kl1']) 'Header/menu startup';[IO.File]::WriteAllBytes((Join-Path $PSScriptRoot 'startup.scr'),[byte[]]$c.M[0x4000..0x5AFF]);$count++
# EDIT is matrix code 7; the legacy input-cancel API returns code 4.
Assert ($bin[$sy['iics']-0xC000+21] -eq 7) 'EDIT key map changed'
foreach($text in @('','1','-1')){$c=Cpu;$c.TimezoneScenario=$true;$c.M[$sy['next_timezone']]=2;$c.Put($sy['INPBUFF'],$text);$c.M[$sy['INLEN']]=$text.Length;$c.Run('set_rtc');Assert ($c.PC -eq 0x2000 -and $c.Carry() -and $c.M[$sy['next_timezone']] -eq 2 -and $c.Commands.Count -eq 0 -and $c.I2cTransactions.Count -eq 0 -and $c.PromptCount -eq 0) 'EDIT failed to cancel GMT before network/RTC';$count++}
# Bypass just the normalization to reproduce the original non-working EDIT.
$c=Cpu;$c.TimezoneScenario=$true;$c.StopAt=$sy['IN2'];$c.M[$sy['IN_EDIT_NORMALIZE']]=195;$c.M[$sy['IN_EDIT_NORMALIZE']+1]=[byte]($sy['IN_EDIT_CODE']-band 255);$c.M[$sy['IN_EDIT_NORMALIZE']+2]=[byte]($sy['IN_EDIT_CODE']-shr 8);$c.Run('set_rtc');Assert ($c.PC -eq $sy['IN2']) 'Original EDIT bug not reproduced';$count++
# A successful SNTP/RTC operation keeps its result visible until an actual key.
$c=Cpu;$c.Run('bios_start');$c.IX=$sy['flag1'];$c.RtcScenario=$true;$c.HoldPrompt=$true;$c.StopAt=$sy['klAP_ret'];$c.Run('set_rtc');Assert ($c.PC -eq $sy['KEYSCAN'] -and $c.PromptCount -eq 1 -and $c.I2cTransactions.Count -eq 2 -and ($c.Messages|Where-Object {$_ -like '*press a key*'}).Count -eq 1) 'RTC result did not wait at press a key';$count++
$c.HoldPrompt=$false;$c.AllowKey=$true;$c.InputResult=65;$c.Resume=$true;$c.Run('KEYSCAN');Assert ($c.PC -eq $sy['klAP_ret'] -and $c.PromptCount -eq 1) 'RTC result did not continue after a key';$count++
# All Next menu entries must reach the setter directly, including 13 and 14.
foreach($index in 0..14){$c=Cpu;$ptr=$sy['speed_table'];for($i=0;$i -lt $index;$i++){while($c.M[$ptr] -ne 0){$ptr++};$ptr++};$c.M[$sy['AP_item']]=[byte]($ptr-band 255);$c.M[$sy['AP_item']+1]=[byte]($ptr-shr 8);$c.StopAt=$sy['sel_spd_go'];$c.Run('select_speed');Assert ($c.L -eq $index -and $c.PC -eq $sy['sel_spd_go']) 'Next menu raised a legacy unsupported-speed warning';$count++}
$c=Cpu;Assert ($c.Str($sy['mbfw']) -eq 'max speed index=') 'Maximum speed index caption';$count++
"PASS: $count Next setup backend scenarios: boot/exit, 120 baud/cache cases, GMT parsing, I2C bytes/signature/NACK/STOP."